@depends("--enable-maintenance-service", when=target_is_windows)
def nsis_installer_files(maintenance_service):
    _INSTALLER_BASE_FILES = (
        "app.tag",
        "nsis/installer.nsi",
        "nsis/uninstaller.nsi",
        "nsis/uninstaller_helpers.nsh",
        "nsis/shared.nsh",
    )
    files = _INSTALLER_BASE_FILES
    if bool(maintenance_service):
        files = _INSTALLER_BASE_FILES + ("nsis/maintenanceservice_installer.nsi",)
    return list(files)


set_config("NSIS_INSTALLER_FILES", nsis_installer_files)
